import heapq


def _dependency_solver(data, direction, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(direction == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        options.append([-1] + versions)

    best_vector = None
    best_install = None
    for values in product(*options):
        selected = {name: version for name, version in zip(names, values)
                    if version != -1}
        valid = True
        for name, bounds in data["roots"].items():
            if name not in selected or not bounds[0] <= selected[name] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        rows = {name: next(row for row in packages[name]
                           if row["version"] == version)
                for name, version in selected.items()}
        edges = {}
        for name, row in rows.items():
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in selected or not dep["min"] <= selected[target] <= dep["max"]:
                    valid = False
                    break
                deps.append(target)
            edges[name] = deps
            if not valid:
                break
        if not valid:
            continue

        closure = set()
        pending = list(data["roots"])
        while pending:
            name = pending.pop()
            if name in closure:
                continue
            closure.add(name)
            pending.extend(edges[name])
        if closure != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(child) for child in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in selected):
            continue

        vector = values
        if best_vector is None or (vector > best_vector if preference == "maximum"
                                   else vector < best_vector):
            best_vector = vector
            best_install = selected
    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (2 * numerator + denominator) // (2 * denominator)
    return numerator // denominator


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        rank = (event.get("revision", 0), pos)
        if event_id not in chosen or rank > chosen[event_id][0]:
            chosen[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        tax = _round(raw * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _schedule(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    for chosen in combinations(jobs, data["k"]):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ends = []
        overlap_ok = True
        for job in sorted(chosen, key=lambda j: (j["start"], j["end"], j["id"])):
            while ends and ends[0] <= job["start"]:
                heapq.heappop(ends)
            heapq.heappush(ends, job["end"])
            if len(ends) > 2:
                overlap_ok = False
                break
        if not overlap_ok:
            continue
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value
                or (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, data["coupons"], initial_mask)
    distances = {initial: data["start"]}
    queue = [(data["start"], source, data["coupons"], initial_mask)]
    while queue:
        time, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and time <= data["deadline"]:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit_for.get(nxt, 0)
                next_state = (nxt, next_remaining, next_mask)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_remaining, next_mask))
    return {"arrival": None}


